3849	    var writer: std.Io.Writer = .fixed(&data);
3850	    input.mouse_encode.encode(&writer, .{
3851	        .button = button,
3852	        .action = action,
3853	        .mods = mods,
3854	        .pos = .{
3855	            .x = pos.x,
3856	            .y = pos.y,
